INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('2f57ecbf-4db7-57ea-a909-88983b58848f', '02f5c1c1-e6ff-5181-837a-2a6b8e03d3f7', 'en', $h$Wall-Mounted Pneumatic Oil Pump 5:1 12 L – 3044$h$, $h$wall-mounted-pneumatic-oil-pump-5-1-12-l-3044$h$, NULL, $h$<div> <div><p><strong>Why the 3044 Wall-Mounted Pneumatic Oil Pump?</strong></p><p>With a 5:1 pressure ratio, this pneumatic oil pump transfers low, medium and high viscosity oils. You can use it for short, medium and long distance transfers. Pump output varies depending on several factors. For example, the pressure of the supplied air and the viscosity and temperature of the fluid all play a role. Hose and connection sizes, as well as the type of gun used, also determine pump output. The operating pressure ranges from a minimum of 6 bar to a maximum of 8 bar. Use filtered and lubricated air to improve the pump's performance and service life. The piston diameter is Ø75 mm. You can easily mount it on a wall with the Model 7120 wall bracket, or install it on an IBC tank.</p></div> </div>$h$, NULL, $h$Wall-Mounted Pneumatic Oil Pump 5:1 12 L – 3044 | HD Marine$h$, $h$Why the 3044 Wall-Mounted Pneumatic Oil Pump? With a 5:1 pressure ratio, this pneumatic oil pump transfers low, medium and high viscosity oils. You can…$h$, 'auto') ON CONFLICT DO NOTHING;
