INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('5794c247-8a02-54b4-b182-0a01c96988af', '1556ada7-64cc-5ee5-8f0f-2c9d31752cb4', 'en', $h$Tank Oil System – TYS4400$h$, $h$tank-oil-system-tys4400$h$, NULL, $h$<div> <div><p><strong>Why the TYS4400 Tank Oil System?</strong></p><p>We designed the tank oil system for small workshops. Its compact structure saves space, and the system holds 208 liters of oil. All the equipment stays in one place, so there is no need to install oil piping. This gives businesses a cost advantage. As standard, we build the TYS4400 from 5 main components. Beyond the standard configuration, you choose your own oil pump, oil gun and oil hose reel. This way you can create new combinations.</p></div> </div>$h$, NULL, $h$Tank Oil System – TYS4400 | HD Marine$h$, $h$Why the TYS4400 Tank Oil System? We designed the tank oil system for small workshops. Its compact structure saves space, and the system holds 208 liters…$h$, 'auto') ON CONFLICT DO NOTHING;
